// Home-screen icons for the trailer pages: a green tile with the trailer's
// number, as PNG. 180 px is what iOS reads for apple-touch-icon; 192 and 512
// are what Android's web-app manifest wants. Generated by PIL, stored as
// base64 so the worker needs no asset bucket for them.

export const TRAILER_ICON_SIZES = [180, 192, 512];

export const TRAILER_ICONS = {
  1: {
    180: '',
    192: '',
    512: '',
  },
  2: {
    180: '',
    192: '',
    512: '',
  },
  3: {
    180: '',
    192: '',
    512: '',
  },
  4: {
    180: '',
    192: '',
    512: '',
  },
  5: {
    180: '',
    192: '',
    512: '',
  },
  6: {
    180: '',
    192: '',
    512: '',
  },
  7: {
    180: '',
    192: '',
    512: '',
  },
  8: {
    180: '',
    192: '',
    512: '',
  },
};

/** PNG bytes for trailer n at the given size, or null. */
export function trailerIconPng(n, size) {
  const icon = TRAILER_ICONS[n];
  const b64 = icon && icon[size];
  if (!b64) return null;
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}
